    fn mask_count() {
        let mask = parse_mask("?d?d", &NO_CUSTOM).unwrap();
        assert_eq!(mask_password_count(&mask), 100);
    }

    #[test]
    fn mask_count_with_literal() {
        let mask = parse_mask("a?d", &NO_CUSTOM).unwrap();
        assert_eq!(mask_password_count(&mask), 10);
    }

